// Find Slack workspaces associated with an email address.
async function findWorkspaces(email: string) {
  try {
    const response = await client.signin.findWorkspaces({ email });
    console.log("Workspaces found:", response.data);
    return response.data;
  } catch (error) {
    console.error("Error finding workspaces:", error);
    return null;
  }
}
```

